30	const PROCESSING_FEE = 5;
31	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
32	
33	const BASE_PREMIUMS: Record<string, number> = {
34	  sword: 100,
35	  amulet: 60,
36	  staff: 80,
37	  potion: 40,
38	  rune: 25,
39	  moonstone: 25,
40	};
41	
42	const CURSE_SURCHARGE_RATE = 0.5;
43	const HIGH_ENCHANTMENT_THRESHOLD = 5;
44	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
45	const LOYALTY_YEARS_THRESHOLD = 2;
46	const LOYALTY_DISCOUNT_RATE = 0.2;
47	
48	const BLOCK_SIZE = 3;
49	const BLOCK_BASE_PREMIUM = 60;
50	
51	const basePremiumForType = (type: string): number => BASE_PREMIUMS[type];
52	
53	const itemBasePremium = (item: Item): number => basePremiumForType(item.type);
54	
55	const countByType = (items: Item[]): Map<string, number> => {
56	  const counts = new Map<string, number>();
57	  for (const item of items) {
58	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
59	  }
60	  return counts;
61	};
62	
63	// A block is exactly BLOCK_SIZE alike items, charged as one unit.
64	const formsBlock = (count: number): boolean => count === BLOCK_SIZE;
65	
66	const groupBasePremium = (type: string, count: number): number =>
67	  formsBlock(count) ? BLOCK_BASE_PREMIUM : count * basePremiumForType(type);
68	
69	const policyBasePremium = (items: Item[]): number =>
70	  [...countByType(items)].reduce(
71	    (total, [type, count]) => total + groupBasePremium(type, count),
72	    0,
73	  );
74	
75	// The MHPCO rounds in its own favour: premiums up, payouts down.
76	const roundUpInMHPCOsFavour = (amount: number): number => Math.ceil(amount);
77	
78	// Item-scoped surcharge clauses. Each applies, independently and additively,
79	// to the affected item's own base premium.
80	const SURCHARGE_CLAUSES: { applies: (item: Item) => boolean; rate: number }[] = [
81	  {
82	    applies: (item) => item.cursed === true,
83	    rate: CURSE_SURCHARGE_RATE,
84	  },
85	  {
86	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
87	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
88	  },
89	];
90	
91	const itemSurcharge = (item: Item): number => {
92	  const base = itemBasePremium(item);
93	
94	  return SURCHARGE_CLAUSES.filter((clause) => clause.applies(item)).reduce(
95	    (total, clause) => total + base * clause.rate,
96	    0,
97	  );
98	};
99	
100	const itemSurcharges = (items: Item[]): number =>
101	  items.reduce((total, item) => total + itemSurcharge(item), 0);
102	
103	const quote = (step: Step, customer: Customer): QuoteResult => {
104	  const policyBase = policyBasePremium(step.items);
105	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
106	  const loyaltyDiscount =
107	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
108	      ? policyBase * LOYALTY_DISCOUNT_RATE
109	      : 0;
110	  const modifiedPremium =
111	    policyBase +
112	    itemSurcharges(step.items) +
113	    firstInsuranceSurcharge -
114	    loyaltyDiscount;
115	
116	  return {
117	    premium: roundUpInMHPCOsFavour(modifiedPremium + PROCESSING_FEE),
118	  };
119	};
120	
121	export const runScenario = (scenario: Scenario): ScenarioResult => ({
122	  results: scenario.steps.map((step) => quote(step, scenario.customer)),
123	});
